"""Solana-specific SigningPartner instances for PKI test infrastructure.

Each instance bundles: PEM key, cert usage, and per-device certificate hex data.
"""

from pathlib import Path
from ledgered.devices import DeviceType
from ragger.pki import SigningPartner, CertificatePubKeyUsage

_KEYCHAIN_DIR = Path(__file__).parent / "keychain"

# pylint: disable=line-too-long
TRUSTED_NAME_PARTNER = SigningPartner(
    pem_key_path=_KEYCHAIN_DIR / "trusted_name.pem",
    cert_pub_key_usage=CertificatePubKeyUsage.TRUSTED_NAME,
    certificates={
        DeviceType.NANOSP: "",
        DeviceType.NANOX:  "",
        DeviceType.STAX:   "",
        DeviceType.FLEX:   "",
        DeviceType.APEX_P: "",
    },
)

DYNAMIC_TOKEN_PARTNER = SigningPartner(
    pem_key_path=_KEYCHAIN_DIR / "dynamic_token.pem",
    cert_pub_key_usage=CertificatePubKeyUsage.COIN_META,
    certificates={
        DeviceType.NANOSP: "",
        DeviceType.NANOX:  "",
        DeviceType.STAX:   "",
        DeviceType.FLEX:   "",
        DeviceType.APEX_P: "",
    },
)

INSTRUCTION_DESCRIPTOR_PARTNER = SigningPartner(
    pem_key_path=_KEYCHAIN_DIR / "instruction_descriptor.pem",
    cert_pub_key_usage=CertificatePubKeyUsage.SWAP_TEMPLATE,
    certificates={
        DeviceType.NANOSP: "",
        DeviceType.NANOX:  "",
        DeviceType.STAX:   "",
        DeviceType.FLEX:   "",
        DeviceType.APEX_P: "",
    },
)

TRANSACTION_CHECK_PARTNER = SigningPartner(
    pem_key_path=_KEYCHAIN_DIR / "transaction_check.pem",
    cert_pub_key_usage=CertificatePubKeyUsage.TX_SIMU_SIGNER,
    certificates={
        DeviceType.NANOSP: "",
        DeviceType.NANOX:  "",
        DeviceType.STAX:   "",
        DeviceType.FLEX:   "",
        DeviceType.APEX_P: "",
    },
)
# pylint: enable=line-too-long
